CREATE OR REPLACE FUNCTION openbot_internal.thread_history_validate_channel_final(p_channel text, p_strict_absence boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_c public.channels%ROWTYPE;v_s openbot_internal.channel_history_sources%ROWTYPE;
 v_channel_found boolean;v_source_found boolean;v_preview text;
BEGIN
 SELECT c.* INTO v_c FROM public.channels c WHERE c.id=p_channel FOR UPDATE OF c NOWAIT;
 v_channel_found:=FOUND;
 SELECT s.* INTO v_s FROM openbot_internal.channel_history_sources s WHERE s.channel_id=p_channel;
 v_source_found:=FOUND;
 IF NOT v_channel_found THEN
  IF v_source_found THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';END IF;
  RETURN;
 END IF;
 IF NOT v_source_found THEN
  IF p_strict_absence AND ROW(v_c.last_message,v_c.last_message_at,v_c.last_message_agent_id)
      IS DISTINCT FROM ROW(NULL::text,NULL::timestamptz,NULL::text) THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
  END IF;
  RETURN;
 END IF;
 PERFORM openbot_internal.thread_history_validate_channel_source(v_s,false);
 SELECT openbot_internal.thread_history_preview(m.search_text) INTO v_preview
  FROM public.messages m WHERE m.message_id=v_s.message_id;
 IF NOT FOUND OR ROW(v_c.last_message,v_c.last_message_at,v_c.last_message_agent_id)
      IS DISTINCT FROM ROW(v_preview,v_s.message_created_at,v_s.last_message_agent_id) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
END;
$function$

