CREATE OR REPLACE FUNCTION openbot_internal.thread_history_validate_channel_source(p_source openbot_internal.channel_history_sources, p_require_open boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_m public.messages%ROWTYPE;v_r public.runs%ROWTYPE;v_t public.threads%ROWTYPE;
 v_preview text;v_agent text;v_open boolean;
BEGIN
 IF p_source.channel_id IS NULL OR p_require_open IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 -- Caller/guard already holds the actual channel EXCLUSIVE row mutex.
 SELECT m.* INTO v_m FROM public.messages m
  JOIN public.runs r ON r.run_id=m.run_id
  JOIN public.threads t ON t.thread_id=r.thread_id AND t.thread_id=m.thread_id
  WHERE m.message_id=p_source.message_id AND m.run_id=p_source.run_id
    AND t.thread_id=p_source.thread_id AND t.anchor_kind='channel'
    AND t.anchor_id=p_source.channel_id FOR SHARE OF m,r,t NOWAIT;
 IF NOT FOUND THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 SELECT r.* INTO v_r FROM public.runs r WHERE r.run_id=v_m.run_id;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';END IF;
 SELECT t.* INTO v_t FROM public.threads t WHERE t.thread_id=v_m.thread_id;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';END IF;
 IF v_m.role='user' AND v_m.actor_id=v_r.actor_id THEN v_agent:=NULL;
 ELSIF v_m.role='assistant' AND v_m.actor_id IS NULL THEN v_agent:=v_r.bot_id;
 ELSE RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';END IF;
 IF pg_catalog.jsonb_typeof(v_m.content) IS DISTINCT FROM 'object' OR
    pg_catalog.jsonb_typeof(v_m.content->'text') IS DISTINCT FROM 'string' OR
    v_m.content->>'text' IS DISTINCT FROM v_m.search_text OR
    ROW(p_source.source_schema,p_source.deployment_id,p_source.tenant_id,p_source.thread_id,
        p_source.run_id,p_source.message_id,p_source.message_role,p_source.message_created_at,p_source.last_message_agent_id)
       IS DISTINCT FROM ROW(1::smallint,v_t.deployment_id,v_t.tenant_id,v_t.thread_id,v_r.run_id,
        v_m.message_id,v_m.role,v_m.created_at,v_agent) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 v_preview:=openbot_internal.thread_history_preview(v_m.search_text);
 IF p_source.preview_checksum IS DISTINCT FROM
     pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_preview,'UTF8'::name)),'hex') OR
    p_source.preview_utf8_bytes IS DISTINCT FROM pg_catalog.octet_length(v_preview) OR
    NOT pg_catalog.isfinite(p_source.message_created_at) OR NOT pg_catalog.isfinite(p_source.recorded_at) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 v_open:=openbot_internal.thread_history_lock_joint(v_t.thread_id,v_r.run_id);
 IF p_require_open AND NOT v_open THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_closed';
 END IF;
END;
$function$

