CREATE OR REPLACE FUNCTION openbot_internal.thread_history_related_channel_ids(p_table text, p_old jsonb, p_new jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_threads text[];v_runs text[];v_messages text[];v_channels text[];v_result text[];
BEGIN
 IF p_table NOT IN('threads','runs','messages','channels','channel_history_sources') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 v_threads:=ARRAY[p_old->>'thread_id',p_new->>'thread_id'];
 v_runs:=ARRAY[p_old->>'run_id',p_new->>'run_id'];
 v_messages:=ARRAY[p_old->>'message_id',p_new->>'message_id'];
 v_channels:=ARRAY[p_old->>'channel_id',p_new->>'channel_id'];
 IF p_table='channels' THEN v_channels:=v_channels||ARRAY[p_old->>'id',p_new->>'id'];END IF;
 IF p_table='threads' THEN
  IF p_old->>'anchor_kind'='channel' THEN v_channels:=v_channels||(p_old->>'anchor_id');END IF;
  IF p_new->>'anchor_kind'='channel' THEN v_channels:=v_channels||(p_new->>'anchor_id');END IF;
 END IF;
 SELECT pg_catalog.array_agg(z.id ORDER BY z.id COLLATE pg_catalog."C") INTO v_result FROM (
  SELECT DISTINCT id COLLATE pg_catalog."C" AS id FROM (
   SELECT x AS id FROM pg_catalog.unnest(v_channels) x WHERE x IS NOT NULL
   UNION ALL SELECT t.anchor_id FROM public.threads t
    WHERE t.anchor_kind='channel' AND (t.thread_id=ANY(v_threads)
     OR EXISTS(SELECT 1 FROM public.runs r WHERE r.run_id=ANY(v_runs) AND r.thread_id=t.thread_id)
     OR EXISTS(SELECT 1 FROM public.messages m WHERE m.message_id=ANY(v_messages) AND m.thread_id=t.thread_id))
   UNION ALL SELECT s.channel_id FROM openbot_internal.channel_history_sources s
    WHERE s.channel_id=ANY(v_channels) OR s.thread_id=ANY(v_threads)
      OR s.run_id=ANY(v_runs) OR s.message_id=ANY(v_messages)
  ) all_ids
 ) z;
 RETURN COALESCE(v_result,ARRAY[]::text[]);
END;
$function$

