CREATE OR REPLACE FUNCTION openbot_internal.thread_history_preview(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_char text; v_code integer; v_out text:=''; v_gap boolean:=false;
 v_count integer:=0; v_i integer;
BEGIN
 -- DB UTF8 was required before creating this function; no locale/POSIX class.
 FOR v_i IN 1..pg_catalog.length(p_text) LOOP
  v_char:=pg_catalog.substr(p_text,v_i,1);v_code:=pg_catalog.ascii(v_char);
  IF v_code<=31 OR v_code BETWEEN 127 AND 159 OR v_code=32 OR
     v_code IN(160,5760,8232,8233,8239,8287,12288) OR
     v_code BETWEEN 8192 AND 8202 THEN
   IF v_count>0 THEN v_gap:=true; END IF;
  ELSE
   IF v_gap THEN v_out:=v_out||' ';v_count:=v_count+1;v_gap:=false;END IF;
   v_out:=v_out||v_char;v_count:=v_count+1;
   -- All remaining characters are nonempty; >200 never shrinks again.
   IF v_count>200 THEN RETURN pg_catalog.substr(v_out,1,199)||U&'\2026'; END IF;
  END IF;
 END LOOP;
 RETURN v_out;
END;
$function$

