CREATE OR REPLACE FUNCTION openbot_internal.guard_channel_history_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_ids text[];v_at timestamptz;v_old jsonb;v_new jsonb;
BEGIN
 IF TG_TABLE_SCHEMA<>'openbot_internal' OR TG_TABLE_NAME<>'channel_history_sources'
    OR TG_OP NOT IN('INSERT','UPDATE','DELETE') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 IF TG_OP<>'INSERT' THEN v_old:=pg_catalog.to_jsonb(OLD);END IF;
 IF TG_OP<>'DELETE' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;
 v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);
 PERFORM openbot_internal.thread_history_lock_channel_ids(v_ids);
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 IF TG_OP='UPDATE' AND (v_old-'recorded_at') IS NOT DISTINCT FROM (v_new-'recorded_at') THEN
  IF NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_source_mutation_refused';
  END IF;
  RETURN NEW;
 END IF;
 SELECT c.last_message_at INTO v_at FROM public.channels c WHERE c.id=NEW.channel_id;
 IF NOT FOUND OR (v_at IS NOT NULL AND NOT v_at<NEW.message_created_at) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_source_order_refused';
 END IF;
 NEW.recorded_at:=pg_catalog.clock_timestamp();
 PERFORM openbot_internal.thread_history_validate_channel_source(NEW,true);
 RETURN NEW;
END;
$function$

