CREATE OR REPLACE FUNCTION openbot_internal.guard_thread_history_canonical_reverse()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_ids text[];v_old jsonb;v_new jsonb;v_keys text[];v_changed boolean;
BEGIN
 IF TG_TABLE_SCHEMA<>'public' OR TG_TABLE_NAME NOT IN('messages','runs','threads') OR
    TG_OP NOT IN('UPDATE','DELETE') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 -- Original target DML has already acquired its canonical row lock. Thus all
 -- newly added channel locks are NOWAIT; no hidden reverse wait order is assumed.
 v_old:=pg_catalog.to_jsonb(OLD);
 IF TG_OP='UPDATE' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;
 v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);
 PERFORM openbot_internal.thread_history_lock_channel_ids(v_ids);
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 -- A preview hash does not fingerprint the entire canonical body or every Run
 -- identity. A final preview comparison alone would miss a change after codepoint
 -- 200 or an assistant Run.actor change. Require the source pointer to be cleared
 -- or moved in this same Tx BEFORE an actual referenced canonical UPDATE. The
 -- subsequent deferred check still verifies the final replacement/NULL relation.
 IF TG_TABLE_NAME='messages' THEN
  v_keys:=ARRAY['message_id','thread_id','run_id','role','actor_id','created_at','content','search_text'];
 ELSIF TG_TABLE_NAME='runs' THEN
  v_keys:=ARRAY['run_id','thread_id','actor_id','bot_id'];
 ELSE
  v_keys:=ARRAY['thread_id','tenant_id','deployment_id','anchor_kind','anchor_id','created_at'];
 END IF;
 SELECT pg_catalog.bool_or(v_old->k IS DISTINCT FROM v_new->k) INTO v_changed
  FROM pg_catalog.unnest(v_keys) k;
 IF v_changed AND EXISTS(SELECT 1 FROM openbot_internal.channel_history_sources s
    WHERE (TG_TABLE_NAME='messages' AND s.message_id=ANY(ARRAY[v_old->>'message_id',v_new->>'message_id']))
       OR (TG_TABLE_NAME='runs' AND s.run_id=ANY(ARRAY[v_old->>'run_id',v_new->>'run_id']))
       OR (TG_TABLE_NAME='threads' AND s.thread_id=ANY(ARRAY[v_old->>'thread_id',v_new->>'thread_id']))) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_source_mutation_refused';
 END IF;
 RETURN NEW;
END;
$function$

