CREATE OR REPLACE FUNCTION openbot_internal.require_thread_history_channel_final()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_old jsonb;v_new jsonb;v_ids text[];v_id text;v_strict boolean;
BEGIN
 IF TG_TABLE_SCHEMA NOT IN('public','openbot_internal') OR TG_TABLE_NAME NOT IN
    ('channels','channel_history_sources','messages','runs','threads') OR
    TG_OP NOT IN('INSERT','UPDATE','DELETE') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 IF TG_OP<>'INSERT' THEN v_old:=pg_catalog.to_jsonb(OLD);END IF;
 IF TG_OP<>'DELETE' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;
 v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);
 v_strict:=TG_TABLE_NAME='channel_history_sources';
 IF TG_TABLE_NAME='channels' THEN
  v_strict:=TG_OP='INSERT' OR TG_OP='DELETE' OR
   ROW(v_old->'last_message',v_old->'last_message_at',v_old->'last_message_agent_id') IS DISTINCT FROM
   ROW(v_new->'last_message',v_new->'last_message_at',v_new->'last_message_agent_id');
 END IF;
 FOREACH v_id IN ARRAY v_ids LOOP
  PERFORM openbot_internal.thread_history_validate_channel_final(v_id,v_strict);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 RETURN NEW;
END;
$function$

