CREATE OR REPLACE FUNCTION openbot_internal.require_thread_history_terminal_final()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openbot_internal'
AS $function$
DECLARE v_ids text[];v_id text;v_terminal_changed boolean:=false;
BEGIN
 IF TG_TABLE_SCHEMA<>'public' OR TG_TABLE_NAME NOT IN('runs','run_events') OR
    TG_OP NOT IN('INSERT','UPDATE','DELETE') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_binding_invalid';
 END IF;
 IF TG_OP='INSERT' THEN v_ids:=ARRAY[NEW.run_id];
 ELSIF TG_OP='DELETE' THEN v_ids:=ARRAY[OLD.run_id];
 ELSE v_ids:=ARRAY[OLD.run_id,NEW.run_id];END IF;
 -- Derive the validation disposition only from this actual trigger event. It is
 -- not caller authority, a GUC, a side ledger, or a durable 'verified' bit.
 IF TG_OP<>'DELETE' THEN
  IF TG_TABLE_NAME='runs' THEN
   IF TG_OP='INSERT' THEN v_terminal_changed:=true;
   ELSE v_terminal_changed:=ROW(OLD.status,OLD.terminal_event_seq,OLD.error_code)
      IS DISTINCT FROM ROW(NEW.status,NEW.terminal_event_seq,NEW.error_code);END IF;
  ELSE
   IF TG_OP='INSERT' THEN v_terminal_changed:=NEW.terminal;
   ELSE v_terminal_changed:=NEW.terminal AND
     ROW(OLD.run_id,OLD.thread_id,OLD.seq,OLD.event_type,OLD.payload,OLD.terminal)
       IS DISTINCT FROM ROW(NEW.run_id,NEW.thread_id,NEW.seq,NEW.event_type,NEW.payload,NEW.terminal);END IF;
  END IF;
 END IF;
 FOR v_id IN SELECT DISTINCT x COLLATE pg_catalog."C" FROM pg_catalog.unnest(v_ids) x
             WHERE x IS NOT NULL ORDER BY x COLLATE pg_catalog."C" LOOP
  PERFORM openbot_internal.thread_history_validate_terminal_run(v_id,v_terminal_changed);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 RETURN NEW;
END;
$function$

